/**
 * The Worker's entry point: the site (built by OpenNext into .open-next/worker.js), plus an
 * hourly Cron Trigger that runs queued jobs such as scheduled publishing.
 */
// @ts-ignore: generated by `npm run cf:build` (absent until then)
import site from './.open-next/worker.js'

type Env = CloudflareEnv & { CRON_SECRET?: string }

export default {
  fetch: site.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const request = new Request(new URL('/api/payload-jobs/run?queue=default', env.NEXT_PUBLIC_SERVER_URL), {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
    })
    ctx.waitUntil(site.fetch(request, env, ctx))
  },
}
